#!/usr/bin/env python3
"""Backend v302 migration INPUT / preflight only. No database writes, no deployment.

Source: successful exact policy delta in CI 45786214184, job 139793529699.
This contains public game catalogue data only, not backend sources or credentials.
Usage: python3 audits/prepare_backend95_pet_migration_v302.py [--output NEW_DIRECTORY]

Server implementation must be based on actual v300 archive and migration 0010:
  1. Validate installed original policy hash; abort on any unexpected version.
  2. Under a maintenance/transaction boundary, install verified new policy;
     preserve catalogue IDs, ownership/source/paid_price, all ledger entries,
     acquisition and chest history, active compensation missions and idempotency
     receipts. Remove only the three retired IDs from future purchase, equip,
     and chest selection. Do not delete historic records or credit wallets.
  3. Normalize only currently equipped retired pet slots to the existing
     pet_none representation, according to the real schema; leave other slots
     unchanged. Do not create inventory entries blindly. Revision invalidation
     must follow the existing profile/economy concurrency contract.
  4. Existing purchased retired pets retain 40% immediate and 80% mission
     compensation using actual recorded paid price. Existing missions remain
     valid; no new rewards or refunds are generated by migration.
  5. Preserve all recorded operation responses; receipt replay precedes new
     policy enforcement so a lost response cannot trigger a second debit.
  6. Deploy client policy validation and server migration as a single gated
     release; until then v302 diagnostic deliberately uses the old policy.
     New requests against retired IDs must be rejected by the server, not merely
     hidden by the client. Do not accept arbitrary client-supplied policy hashes.
  7. On a disposable PostgreSQL database, apply real Alembic migration after
     0010, verify upgrade from seeded old DB and fresh installation, run full
     suite plus concurrent buy/equip/chest/sale and lost-receipt replay, cross-
     profile isolation, mission completion, historical chest counts and actual
     Vue+API online/offline/F5 acceptance. Compare wallet, history, and ownership
     before/after; retry migration safely, check rollback on injected failure.
     No PostgreSQL or real schema was available for this preflight.
  8. No production migration or downgrade is authorized. A rollback plan must
     account for operations made after switching policy, not restore a stale DB.
"""
import argparse
import base64
import gzip
import hashlib
import json
from pathlib import Path

OLD_SHA = "e12e0b972331ecf508f40a0e9a5b285d205807844222d2191260d91a88e54c43"
NEW_SHA = "81ddda0d0993f34aad16dfdf9d354a50691837049cd2ef25556c0daa7ae75953"
OLD_BUILD = "bec1537186acb23b7483d98f8fabf3b3870def64e255cfcec5208d659851ecce"
NEW_BUILD = "2027d86fd81013019c376b14eb20f07e95ba3c361c4310944904e1b6dc37f18d"
RETIRED = ("pet_robotx", "pet_wisecat", "pet_royal_dragon")

# Captured exact exports, retaining the original bytes rather than reserializing.
OLD_GZIP_B64 = ""
NEW_GZIP_B64 = ""

def require(condition, message):
    if not condition:
        raise ValueError(message)

def unpack(encoded, digest):
    raw = gzip.decompress(base64.b64decode(encoded, validate=True))
    require(hashlib.sha256(raw).hexdigest() == digest, "Policy digest mismatch")
    return raw, json.loads(raw)

def preflight():
    old_raw, old = unpack(OLD_GZIP_B64, OLD_SHA)
    new_raw, new = unpack(NEW_GZIP_B64, NEW_SHA)
    require(old["build"] == OLD_BUILD and new["build"] == NEW_BUILD, "Build digest mismatch")
    items = {item["id"]: item for item in old["items"]}
    require(len(items) == 261 == len(old["items"]), "Original catalogue mismatch")
    require(all(i in items and items[i]["category"] == "pets" and items[i]["buyable"] and items[i]["selectable"] for i in RETIRED), "Unexpected retired item state")
    old["build"] = NEW_BUILD
    for i in RETIRED:
        items[i]["buyable"] = items[i]["selectable"] = False
    old["pools"] = {r: [i for i in ids if i not in RETIRED] for r, ids in old["pools"].items()}
    require(old == new, "Unapproved policy delta")
    require(sum(i["buyable"] for i in new["items"]) == 181, "Unexpected buyable count")
    require({r: len(ids) for r, ids in new["pools"].items()} == {"rare": 19, "epic": 15, "legendary": 10}, "Unexpected pool sizes")
    return old_raw, new_raw

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--output", type=Path, help="New, nonexisting directory for verified inputs")
    args = parser.parse_args()
    old_raw, new_raw = preflight()
    if args.output:
        args.output.mkdir(parents=True, exist_ok=False)
        (args.output / "economy_v290.json").write_bytes(old_raw)
        (args.output / "economy_v302_candidate.json").write_bytes(new_raw)
    print("PASS_POLICY_INPUT_PREFLIGHT", NEW_SHA)
    print("NO_DATABASE_CHANGES: real server schema, migration and tests still required")

if __name__ == "__main__":
    main()
